insert into public.academy_content(id,kind,title,course_id,payload,published,restaurant_id,department) values ('guru-42875','course','🔵Как пользоваться ServiceGuru',null,'{"id":"guru-42875","title":"🔵Как пользоваться ServiceGuru","shortTitle":"🔵Как пользоваться ServiceGuru","coverLabel":"🔵Как пользоваться ServiceGuru","description":"Инструкции по работе с учебной платформой.","kind":"course","brand":"90-е","departments":["Зал","Бар","Кухня","Арт","Кальян","Руководитель"],"positions":[],"restaurantIds":["pushkino","khimki","mytishchi"],"questions":[],"pass":80,"lessons":[{"title":"Эффективное использование ServiceGuru","text":"Приложение ServiceGuru\n\nПриветствуем, коллеги!\n\nВпереди вас ждёт увлекательное обучение в приложении ServiceGuru 🤓\n\nServiceGuru - это приложение для обучения и заботы о сотрудниках. Наше приложение мотивирует, превращая процесс обучения в захватывающую игру.\n\nМобильное приложение, позволяет сотрудникам получать оперативный доступ к материалам, инструкциям, стандартам в любое время, изучать меню, проходить тестирования и аттестации, получать новости компании в режиме онлайн.\n\nServiceGuru существует, чтобы вы быстро и качественно обучились, чтобы вы более детально изучили все стандарты и инструкции по вашей должности. Вам будет проще и удобнее учить меню, т.к. в приложении наглядно можно увидеть фото блюд и напитков ресторана, легче запоминать составы. Информация подаётся понятным и удобным способом, процесс запоминания происходит в разы быстрее ⏰\n\nВы сможете оперативнее сдать аттестацию на закрытие стажировки и приступить к работе с гостями или на кухне. Следовательно, если вы работник зала, то чем быстрее вы приступите к работе с гостями и будете качественно с ними работать, показывая идеальный сервис, вы станете больше зарабатывать💰А мы знаем, что вас всегда мотивируют хороший заработок и большие чаевые!\n\nПредставьте, что вы быстрее выйдете на достойные чаевые, и они постоянно будут увеличиваться, т.к. после эффективного обучения в ServiceGuru, вы станете профессионалом в своей должности. В процессе использования ServiceGuru повышается качество вашего сервиса. Вы сможете уверенно и элегантно работать с гостями, регулярно увеличивая свой доход 💵","images":["assets/remaining-courses/guru-42875-99811-0.jpg","assets/remaining-courses/guru-42875-99811-1.jpg"],"links":[],"id":"99811"},{"title":"Инструкция по работе с ServiceGuru","text":"Начало\n\nВ приложении есть 4 основных вкладки:\n\nГлавная\nОбучение\nСообщения\nПрофиль\nВкладка \"Главная\"\n\nПосле входа в приложение нам открывается вкладка “Главная”.\n\nСверху мы видим назначенные на вас курсы, ниже будут высвечиваться закрепленные новости и разделение всех основных новостей на 4 раздела.\n\nДля вас - Сюда подтягиваются абсолютно все новости, назначенные курсы, обновления в меню и т.п.\n\nВкладка \"Обучение\"\n\nРаздел \"Учебные курсы\"\n\nЗдесь отображаются учебные курсы назначенные на вас.\n\nКурсы обычно разделены на уровни - Базовый уровень - Уровень профи - Уровень эксперт.\n\nВ учебном курсе доступны уроки с теорией и тесты.\n\nВ данной вкладке находятся все обучающие материалы доступные для сотрудника. Она включает в себя следующие разделы:\n\nУчебные курсы\nМеню и стандарты\nАттестации\nОпросы\nБиблиотека\n\nРаздел \"Меню и стандарты\"\n\nЗдесь отображаются карточки блюд и напитков. Все меню поделено на разделы.\n\nРаздел \"Аттестации\"\n\nЗдесь отображаются назначенные и пройдённые аттестации.\n\nРаздел \"Опросы\"\n\nЗдесь отображаются активные доступные и пройдённые опросы.\n\nРаздел \"Библиотека\"\n\nЭто хранилище учебных материалов. Здесь могут быть учебные материалы в разных форматах.\n\nВкладка \"Профиль\"\n\nТут можно увидеть доступные графики работы, рейтинг, уровень, количество набранных очков и сертификаты. При нажатии на значок Шестеренки, можно войти в Настройки и изменить язык приложения, выйти или удалить профиль.\n\nПри нажатии на восклицательный знак, можно увидеть версию приложения, оставить отзыв, и прочитать политику конфиденциальности.","images":["assets/remaining-courses/guru-42875-99812-0.jpg","assets/remaining-courses/guru-42875-99812-1.jpg","assets/remaining-courses/guru-42875-99812-2.jpg","assets/remaining-courses/guru-42875-99812-3.jpg","assets/remaining-courses/guru-42875-99812-4.jpg"],"links":[],"id":"99812"}],"outline":[{"type":"lesson","title":"Эффективное использование ServiceGuru","lessonIndex":0},{"type":"lesson","title":"Инструкция по работе с ServiceGuru","lessonIndex":1}],"testIds":[]}'::jsonb,true,null,null) on conflict(id) do update set kind=excluded.kind,title=excluded.title,course_id=excluded.course_id,payload=excluded.payload,published=excluded.published,restaurant_id=excluded.restaurant_id,department=excluded.department;
insert into public.academy_content(id,kind,title,course_id,payload,published,restaurant_id,department) values ('guru-43403','course','Правила сотрудника Бара "90-е"',null,'{"id":"guru-43403","title":"Правила сотрудника Бара \"90-е\"","shortTitle":"Правила сотрудника Бара \"90-е\"","coverLabel":"Правила сотрудника Бара &quot;90-е&quot;","description":"Основные принципы работы, общение в чатах и правила поведения на смене.","kind":"course","brand":"90-е","departments":["Зал","Бар","Кухня","Арт","Кальян","Руководитель"],"positions":[],"restaurantIds":["pushkino","khimki","mytishchi"],"questions":[],"pass":80,"lessons":[{"title":"Основные принципы работы","text":"🔴Важно!🔴\nГостям запрещено сидеть на подлокотниках и спинках мебели\nГостям запрещается проходить в зал в верхней одежде, также запрещено отдавать пледы в зал\nЗапрещено продавать блюда в баре на самовывоз, такой заказ пробивается по ценам доставки (даже для персонала)\nСкидочные карты сети не работают в наших барах, прокатывать их запрещено, скидка делается вручную (максимально - 40%)\nВ ПТ и СБ с 23:00 до 03:00 персонал не выходит на перекур. Исключение: допускается выйти на перекур в случае малого количества гостей\nМеню на столах мы не оставляем, всегда убираем его после принятия заказа и подаем по запросу\nЕсли на столе остаются напитки (алкогольные и безалкогольные) , официант должен вернуть их в бар. Никто не может забрать напитки с собой или выпить их!\nВходными картами пользуются только гости. Официант не может использовать карты гостей и забирать напитки. Если вы нашли потерянную карту, ее необходимо вернуть на бар.\n🔴Представительские столы \n\nОбслуживание:\n\nНе подаём текстильные салфетки, используем только красные, за исключением ситуаций, когда руководители сидят с незнакомым человеком.\nТо, что заказывает руководитель, бьется на представительский стол, заказ остальных гостей стола в обычном порядке, по номеру стола за которым они находятся (если нет иного распоряжения)\n\n🔴Номера столов\n\n111 - Генеральный директор Разумов Дмитрий Владимирович\n\n222 - Арт директор Крыгин Алексей\n\n333 - Операционный директор Кучер Александр Сергеевич\n\n444 - Бар-менеджер Усов Аркадий\n\n555 - Управляющий РВБХ Слабый Сергей Павлович\n\n666 - Управляющий РВБП Саргсян Мариам Суреновна\n\n777 - Тех.Директор\n\n888 - Арт-халява ( диджей, мс, световик, фотограф). У диджея и мс депозит равный 1000₽ только на напитки, еду и алкоголь (по согласованию с менеджером). У фотографа - один напиток.\n\n999 - Бренд шеф-повар Камбалов Виталий Николаевич\n\n1000 - Охрана\n\n1001 - Менеджеры\n\nШарымов Дмитрий Владимирович - заместитель генерального директора. Пробивается на любой стол и подписывается Шарымов.\n\n🔴Фишки для персонала\nКаждый сотрудник, который отработал год в нашем баре, получает ежемесячную доплату за выслугу лет в размере 1000 руб.\nУ всех сотрудников бара есть скидка 40% на напитки и кальяны, покупка алкоголя согласовывается с менеджером/управляющим (при этом, сотрудник должен быть в момент покупки на выходном). \nРаспивать алкоголь в рабочее и нерабочее время, находясь на территории бара, запрещено.\nПерсонал не пьёт из гостевой посуды если, конечно, не купил бокальную позицию из бара.\nК управляющему, операционному директору и генеральному директору всегда на вы.","images":[],"links":[],"id":"101496"},{"title":"Правила поведения в чатах","text":"👣❌ Каждый сотрудник обязан указать в личной карте Telegram свою фамилию и имя для идентификации.\n\n✍️🙋‍♂️ Все обращения к руководству должны быть исключительно на «Вы».\n\n💃🕺Сотрудники бара состоят в нескольких чатах, поэтому сообщения должны соответствовать теме. Не стоит засорять чаты ненужной информацией. Если хотите пошутить и уверены, что это будет уместно — можно, но в разумных пределах🤭\n\n🔞 Если вы считаете ситуацию в чате возмутительной или вас оскорбили, не вступайте в конфликт — обратитесь к менеджеру. Он поможет наказать мерзавца. Если менеджер не может помочь или конфликт произошел с ним, опишите суть проблемы управляющему в личном сообщении или дождитесь личной встречи. У каждого управляющего есть «плеть», так что последствия могут быть серьезными😏\n\n🍒⭐ Чат A3Kteam должен быть закреплен в топике. Далее закрепляем чат Штат, далее профильные чаты должности и все это помещаем в отдельную группу чатов rvb. Уведомления обязательно включены на первые 3 чата\n\n❓😆 Если в чате задают вопрос, вы обязаны ознакомиться с ним и дать ответ. Игнорировать рабочие вопросы, особенно касающиеся вас, запрещено!","images":[],"links":[{"title":"Чат A3Kteam","url":"https://t.me/A3Kteam"}],"id":"101495"},{"title":"Правила поведения на смене","text":"❌ Что нельзя делать персоналу на смене:\nКурить сигареты в помещении бара\nКурить кальян, без согласования управляющего\nОтлучаться с рабочего места, в прайм-тайм, на поесть и сходить в туалет - только с согласования менеджера.\nНаходиться на рабочем месте в наркотическом состоянии\nНаходиться на рабочем месте в сильном алкогольном опьянении\nНаходиться в заведении, после окончания смены - только с разрешения управляющего.\nХранить личные вещи в зоне видимости гостей\nКрасть имущество бара, гостей и сотрудников\nЛюбые махинации со счетами/деньгами\nЕсть и пить в зале в зоне видимости гостей\nПортить имущество бара\nНетактично вести себя с гостями и сотрудниками бара\nПринимать еду, напитки в неположенном месте, в неположенное время\nЗапрещается играть в игры на телефоне, в рабочее время\nЗапрещается работать в нерабочей форме\nЗапрещается сон на рабочем месте\nЗапрещается работать в грязной обуви и форме\nЗапрещается брать деньги за «депозит», кроме хостес и менеджера\nЗапрещается петь песни в караоке\nУгощать дам, друзей и тд товаром взятым из бара, без списания по кассе\nИсключена история: «забыл пробить по запаре»\nЗапрещается обналичивать безналичные деньги\nЗапрещается делать двойную скидку(бартер + скидочная карта)\nЗапрещается есть на раздаче кухни, есть еду после гостей\nЗапрещается курить в зоне кухни\nОставленные вещи на раздаче кухни или в неположенном месте, будут утилизированы в момент обнаружения\nЗапрещено пользоваться телефоном в зале, исключением является принятие заказа и заметки по работе на собрании.\nПокидать смену\\Уходить с рабочего места по собственному желанию.\nЗапрещается употребление пищи и напитков из гостевой посуды.\nЗапрещается принимать переводы на личные карты от гостей.\n\nУволившийся сотрудник не может посещать 90-е Бар МХП сроком от 3 месяцев до полного запрета.\n\nВ случае несоблюдения вышеперечисленного, будет рассматриваться увольнение без выплаты З\\П","images":[],"links":[],"id":"101616"}],"outline":[{"type":"lesson","title":"Основные принципы работы","lessonIndex":0},{"type":"lesson","title":"Правила поведения в чатах","lessonIndex":1},{"type":"lesson","title":"Правила поведения на смене","lessonIndex":2},{"type":"test","title":"Тест. Правила сотрудника РВБ"}],"testIds":["94440"]}'::jsonb,true,null,null) on conflict(id) do update set kind=excluded.kind,title=excluded.title,course_id=excluded.course_id,payload=excluded.payload,published=excluded.published,restaurant_id=excluded.restaurant_id,department=excluded.department;
commit;
